//     @(posedge vif.clk);
//     seq_item_port.get_next_item(req);
//     @(posedge vif.clk);
//     drive(req);
//     seq_item_port.item_done();
//   end

class bus_driver extends uvm_driver #(bus_item);
  `uvm_component_utils(bus_driver)
  virtual bus_if vif;            // clocking block cb: output valid, addr, data; input ready
  function new(string name, uvm_component parent); super.new(name, parent); endfunction

  task run_phase(uvm_phase phase);
    vif.cb.valid <= 1'b0;
    wait (vif.rst_n === 1'b1);
    @(vif.cb);                                   // align to a clock edge once
    forever begin
      seq_item_port.try_next_item(req);          // no wait if an item is already queued
      if (req == null) begin
        vif.cb.valid <= 1'b0;                    // bubble only when nothing is available
        @(vif.cb);
        continue;
      end
      vif.cb.valid <= 1'b1;                      // takes effect at this edge
      vif.cb.addr  <= req.addr;
      vif.cb.data  <= req.data;
      @(vif.cb);
      while (vif.cb.ready !== 1'b1) @(vif.cb);   // hold until accepted
      seq_item_port.item_done();                 // release the sequencer immediately
    end
  endtask
endclass

class traffic_test extends base_test;
  `uvm_component_utils(traffic_test)
  function new(string name, uvm_component parent); super.new(name, parent); endfunction

  task reset_phase(uvm_phase phase);
    phase.raise_objection(this);
    env.rst_agt.apply_reset(20);                 // reset completes before main_phase
    phase.drop_objection(this);
  endtask

  task main_phase(uvm_phase phase);
    traffic_seq seq = traffic_seq::type_id::create("seq");
    phase.raise_objection(this);                 // keeps main_phase alive
    seq.start(env.agt.sqr);
    phase.drop_objection(this);
  endtask
endclass
```

### Corner cases & pitfalls
- Never mix `get_next_item`/`item_done` with `get`/`put` in one driver; calling `item_done` twice is a fatal error.
- Starting a sequence in `run_phase` while reset is applied in `reset_phase` (or vice versa) creates races; keep both in run-time phases or both in `run_phase` with explicit reset waits.
- With a pipelined protocol, use separate request/response threads (or `get` + `put`) so a long response does not block the next request.
- Add `phase.phase_done.set_drain_time()` (or `set_drain_time` on the objection) so the last items finish before the phase ends.

### Follow-ups
- *`try_next_item` vs `get_next_item`?* `try_next_item` returns null instead of blocking, so the driver can insert idle cycles itself.
- *How do you prove back-to-back throughput?* A cover property for `valid && ready` on consecutive cycles, plus a monitor-side bandwidth check.

linkedin-uvm-003:
**Key idea:** Use **`extract_phase`**. It is the first cleanup phase: it runs after `run_phase` and every run-time phase have ended and before `check_phase`. It is a zero-time **function**, meant for collecting final state (scoreboard leftovers, coverage numbers, DUT status already mirrored) so that `check_phase` can judge it. If the extra work **consumes simulation time** (draining, register reads), it cannot go there: put it in `post_shutdown_phase` (or delay the end of `run_phase` with `phase_ready_to_end`).

```mermaid
flowchart LR
  B["build"] --> C["connect"] --> E["end_of_elaboration"] --> S["start_of_simulation"]
  S --> R["run_phase, in parallel with reset to post_shutdown"]
  R --> X["extract_phase: zero time, collect"]
  X --> K["check_phase: pass or fail"]
  K --> RP["report_phase"] --> F["final_phase"]
```

### Code
```systemverilog
class my_scoreboard extends uvm_scoreboard;
  `uvm_component_utils(my_scoreboard)
  bus_item exp_q[$];
  int      n_left;
  real     cov_pct;
  bus_cov  cov;                          // coverage subscriber handle

  function new(string name, uvm_component parent); super.new(name, parent); endfunction

  // Zero-time collection after all stimulus and run-time activity has ended
  function void extract_phase(uvm_phase phase);
    super.extract_phase(phase);
    n_left  = exp_q.size();
    cov_pct = cov.cg.get_coverage();
  endfunction

  function void check_phase(uvm_phase phase);
    super.check_phase(phase);
    if (n_left != 0)
      `uvm_error("SCB", $sformatf("%0d expected transactions never observed", n_left))
  endfunction

  function void report_phase(uvm_phase phase);
    `uvm_info("SCB", $sformatf("functional coverage = %0.2f%%", cov_pct), UVM_LOW)
  endfunction
endclass

// Time-consuming wrap-up: do it while simulation time can still advance
class my_env extends uvm_env;
  `uvm_component_utils(my_env)
  function new(string name, uvm_component parent); super.new(name, parent); endfunction

  task post_shutdown_phase(uvm_phase phase);
    phase.raise_objection(this);
    wait_dut_idle();          // e.g. wait for FIFOs to drain
    read_status_regs();       // RAL front-door reads consume time
    phase.drop_objection(this);
  endtask

  virtual task wait_dut_idle(); endtask
  virtual task read_status_regs(); endtask
endclass
```

### Explanation
- Order of the cleanup phases (all functions, executed bottom-up): `extract` → `check` → `report` → `final`.
- `run_phase` runs in parallel with the 12 run-time phases; `post_shutdown_phase` is the last run-time phase, so it is the last chance to spend time before `extract`.
- `phase_ready_to_end(uvm_phase phase)` can re-raise an objection to postpone the end of a phase until outstanding transactions finish.

### Corner cases & pitfalls
- A `#delay` or `@event` inside `extract_phase` is a compile error (it is a function).
- Do not judge pass/fail in `extract_phase`; keep extract for gathering and `check_phase` for verdicts so that every component's data is ready first.
- Forgetting the objection in `post_shutdown_phase` makes it end at time 0 of that phase.

### Follow-ups
- *Why bottom-up for cleanup phases?* Children (monitors, scoreboards) finish collecting before parents summarize.
- *Can a component jump phases?* Yes, `phase.jump(uvm_reset_phase::get())` for mid-test reset, but only between run-time phases.

